<?php
declare(strict_types=1);require_once __DIR__.'/../../config/ui.php';require_login('ADMIN');$error='';$success='';$preview=[];
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();if(empty($_FILES['planilha']['tmp_name']))throw new InvalidArgumentException('Selecione uma planilha CSV.');$fh=fopen($_FILES['planilha']['tmp_name'],'rb');$header=fgetcsv($fh,0,';');if(!$header)$header=fgetcsv($fh,0,',');$header=array_map(fn($v)=>strtolower(trim((string)$v)),$header?:[]);$required=['nome','email','telefone','cpf','matricula','senha','foto_url'];if(array_diff($required,$header))throw new InvalidArgumentException('Colunas obrigatórias: '.implode(', ',$required));while(($line=fgetcsv($fh,0,';'))!==false){if(count($line)<count($header)){$line=fgetcsv($fh,0,',');}if(!$line||count($line)<count($header))continue;$row=array_combine($header,$line);if(filter_var(trim($row['email']),FILTER_VALIDATE_EMAIL)&&trim($row['nome'])&&trim($row['cpf'])&&trim($row['matricula']))$preview[]=$row;}fclose($fh);if(isset($_POST['confirmar'])){if(!$preview)throw new InvalidArgumentException('A planilha não possui registros válidos.');$pdo->beginTransaction();$pdo->exec("DELETE FROM usuarios WHERE perfil='ASSOCIADO'");$dir=__DIR__.'/../uploads/associados';if(!is_dir($dir))mkdir($dir,0755,true);$insert=$pdo->prepare("INSERT INTO usuarios(nome,email,telefone,cpf,senha_hash,perfil,status_financeiro,matricula,data_filiacao,foto) VALUES(?,?,?,?,?,'ASSOCIADO','EM_DIA',?,CURDATE(),?)");$count=0;foreach($preview as $r){$foto=null;$url=filter_var(trim($r['foto_url']),FILTER_VALIDATE_URL);if($url){$content=@file_get_contents($url);if($content!==false){$foto='import_'.bin2hex(random_bytes(8)).'.jpg';file_put_contents($dir.'/'.$foto,$content);}}$insert->execute([trim($r['nome']),trim($r['email']),trim($r['telefone']),trim($r['cpf']),password_hash($r['senha']?:'Nexus@123',PASSWORD_ARGON2ID),trim($r['matricula']),$foto]);$count++;}audit('IMPORTACAO_ASSOCIADOS','usuarios',null,['registros'=>$count]);$pdo->commit();$success="$count associados importados. Os associados anteriores foram removidos; o administrador foi preservado.";$preview=[];}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof InvalidArgumentException?$e->getMessage():'Falha na importação.';}}
admin_start('Importar associados','associados.php');?><div class="mb-8"><p class="mb-2 text-sm font-semibold text-blue-600">Carga de dados</p><h2 class="text-3xl font-extrabold">Importar associados</h2><p class="mt-2 text-sm text-slate-500">Envie uma planilha CSV para substituir a base de associados.</p></div><?php if($success):?><div class="mb-5 rounded-lg bg-emerald-50 p-4 text-sm text-emerald-700"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="mb-5 rounded-lg bg-red-50 p-4 text-sm text-red-700"><?=e($error)?></div><?php endif;?><div class="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800"><b>Atenção:</b> ao confirmar, todos os associados atuais serão removidos. O utilizador ADMIN será preservado.</div><form method="post" enctype="multipart/form-data" class="shadow-soft mt-6 max-w-2xl rounded-xl bg-white p-7"><?=csrf_field()?><label class="block text-sm font-semibold">Planilha CSV<input type="file" name="planilha" accept=".csv,text/csv" required class="mt-2 block w-full rounded-lg border border-slate-200 p-3 text-sm"></label><p class="mt-3 text-xs text-slate-500">Use separador ponto e vírgula. Colunas: nome;email;telefone;cpf;matricula;senha;foto_url</p><div class="mt-6 flex gap-3"><button class="rounded-lg bg-blue-600 px-5 py-3 text-sm font-bold text-white">Pré-visualizar</button><?php if($preview):?><button name="confirmar" class="rounded-lg bg-red-600 px-5 py-3 text-sm font-bold text-white">Confirmar substituição (<?=count($preview)?>)</button><?php endif;?></div></form><?php if($preview):?><div class="shadow-soft mt-6 overflow-x-auto rounded-xl bg-white p-6"><h3 class="mb-4 font-bold">Pré-visualização</h3><table class="w-full text-left text-sm"><tr class="border-b text-xs uppercase text-slate-400"><th class="p-3">Nome</th><th class="p-3">E-mail</th><th class="p-3">Matrícula</th><th class="p-3">Foto</th></tr><?php foreach($preview as $r):?><tr class="border-b"><td class="p-3"><?=e($r['nome'])?></td><td class="p-3"><?=e($r['email'])?></td><td class="p-3"><?=e($r['matricula'])?></td><td class="p-3 text-emerald-600">Disponível</td></tr><?php endforeach;?></table></div><?php endif;?><?php admin_end();